-- Complete Scripture Import for BOM Study Tools
-- Run this entire file in Supabase SQL Editor
-- Column names: snake_case (edition_id, verse_type)

-- Step 1: Enable INSERT permissions temporarily
CREATE POLICY IF NOT EXISTS "temp_allow_verse_insert"
  ON verses FOR INSERT
  WITH CHECK (true);

CREATE POLICY IF NOT EXISTS "temp_allow_cross_ref_insert"
  ON cross_references FOR INSERT
  WITH CHECK (true);

-- Step 2: Import Book of Mormon verses
-- (8488 verses)

INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-1', 'coc-bom-1908', 'I Nephi', 1, 1, 'I, Nephi, having been born of goodly parents, therefore, I was taught somewhat in all the learning of my father;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-2', 'coc-bom-1908', 'I Nephi', 1, 2, 'And I know that the record which I make is true;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-3', 'coc-bom-1908', 'I Nephi', 1, 3, 'For it came to pass in the commencement of the first year of the reign of Zedekiah, king of Judah (my father Lehi having dwelt at Jerusalem in all his days), and in that same year there came many prophets, prophesying unto the people that they must repent or the great city Jerusalem must be destroyed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-4', 'coc-bom-1908', 'I Nephi', 1, 4, 'Wherefore, it came to pass that my father Lehi, as he went forth, prayed unto the Lord, yea, even with all his heart in behalf of his people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-5', 'coc-bom-1908', 'I Nephi', 1, 5, 'And it came to pass as he prayed unto the Lord, there came a pillar of fire and dwelt upon a rock before him;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-6', 'coc-bom-1908', 'I Nephi', 1, 6, 'And it came to pass that he returned to his own house at Jerusalem;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-7', 'coc-bom-1908', 'I Nephi', 1, 7, 'And being thus overcome with the Spirit, he was carried away in a vision, even that he saw the heavens open;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-8', 'coc-bom-1908', 'I Nephi', 1, 8, 'And it came to pass that he saw one descending out of the midst of heaven, and he beheld that his luster was above that of the sun at noonday;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-9', 'coc-bom-1908', 'I Nephi', 1, 9, 'And he also saw twelve others following him, and their brightness did exceed that of the stars in the firmament;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-10', 'coc-bom-1908', 'I Nephi', 1, 10, 'And the first came, and stood before my father, and gave unto him a book, and bade him that he should read.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-11', 'coc-bom-1908', 'I Nephi', 1, 11, 'And it came to pass that as he read, he was filled with the Spirit of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-12', 'coc-bom-1908', 'I Nephi', 1, 12, 'Yea, and many things did my father read concerning Jerusalem--that it should be destroyed, and the inhabitants thereof, many should perish by the sword, and many should be carried away captive into Babylon.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-13', 'coc-bom-1908', 'I Nephi', 1, 13, 'And it came to pass that when my father had read and seen many great and marvelous things, he did exclaim many things unto the Lord, such as, Great and marvelous are thy works, O Lord God Almighty! Thy throne is high in the heavens, and thy power, and goodness, and mercy are over all the inhabitants of the earth;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-14', 'coc-bom-1908', 'I Nephi', 1, 14, 'And after this manner was the language of my father in the praising of his God;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-15', 'coc-bom-1908', 'I Nephi', 1, 15, 'And now, I, Nephi, do not make a full account of the things which my father hath written, for he hath written many things which he saw in visions and in dreams;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-16', 'coc-bom-1908', 'I Nephi', 1, 16, 'And he also hath written many things which he prophesied and spake unto his children, of which I shall not make a full account;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-17', 'coc-bom-1908', 'I Nephi', 1, 17, 'Behold, I make an abridgment of the record of my father upon plates which I have made with mine own hands;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-18', 'coc-bom-1908', 'I Nephi', 1, 18, 'Therefore, I would that ye should know that after the Lord had shown so many marvelous things unto my father Lehi, yea, concerning the destruction of Jerusalem, behold, he went forth among the people and began to prophesy and to declare unto them concerning the things which he had both seen and heard.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-19', 'coc-bom-1908', 'I Nephi', 1, 19, 'And it came to pass that the Jews did mock him because of the things which he testified of them;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-20', 'coc-bom-1908', 'I Nephi', 1, 20, 'And he testified that the things which he saw and heard, and also the things which he read in the book, manifested plainly of the coming of a Messiah and also the redemption of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-21', 'coc-bom-1908', 'I Nephi', 1, 21, 'And when the Jews heard these things, they were angry with him, yea, even as with the prophets of old, whom they had cast out, and stoned, and slain;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-22', 'coc-bom-1908', 'I Nephi', 1, 22, 'And they also sought his life, that they might take it away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-23', 'coc-bom-1908', 'I Nephi', 1, 23, 'But behold, I, Nephi, will show unto you that the tender mercies of the Lord are over all those whom he hath chosen, because of their faith, to make them mighty even unto the power of deliverance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-24', 'coc-bom-1908', 'I Nephi', 1, 24, 'For behold, it came to pass that the Lord spake unto my father, yea, even in a dream, and said unto him, Blessed art thou, Lehi, because of the things which thou hast done;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-25', 'coc-bom-1908', 'I Nephi', 1, 25, 'And because thou hast been faithful and declared unto this people the things which I commanded thee, behold, they seek to take away thy life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-26', 'coc-bom-1908', 'I Nephi', 1, 26, 'And it came to pass that the Lord commanded my father, even in a dream, that he should take his family and depart into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-27', 'coc-bom-1908', 'I Nephi', 1, 27, 'And it came to pass that he was obedient unto the word of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-28', 'coc-bom-1908', 'I Nephi', 1, 28, 'And it came to pass that he departed into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-29', 'coc-bom-1908', 'I Nephi', 1, 29, 'And he left his house, and the land of his inheritance, and his gold, and his silver, and his precious things, and took nothing with him, save it were his family, and provisions, and tents;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-30', 'coc-bom-1908', 'I Nephi', 1, 30, 'And he came down by the borders near the shore of the Red Sea;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-31', 'coc-bom-1908', 'I Nephi', 1, 31, 'And he traveled in the wilderness in the borders which were nearer the Red Sea;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-32', 'coc-bom-1908', 'I Nephi', 1, 32, 'And he did travel in the wilderness with his family, which consisted of my mother Sariah, and my elder brothers, who were Laman, Lemuel, and Sam.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-33', 'coc-bom-1908', 'I Nephi', 1, 33, 'And it came to pass that when he had traveled three days in the wilderness, he pitched his tent in a valley by the side of a river of water.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-34', 'coc-bom-1908', 'I Nephi', 1, 34, 'And it came to pass that he built an altar of stones, and he made an offering unto the Lord and gave thanks unto the Lord, our God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-35', 'coc-bom-1908', 'I Nephi', 1, 35, 'And it came to pass that he called the name of the river Laman, and it emptied into the Red Sea;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-36', 'coc-bom-1908', 'I Nephi', 1, 36, 'And when my father saw that the waters of the river emptied into the fountain of the Red Sea, he spake unto Laman, saying, Oh, that thou mightest be like unto this river, continually running into the fountain of all righteousness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-37', 'coc-bom-1908', 'I Nephi', 1, 37, 'And he also spake unto Lemuel: Oh, that thou mightest be like unto this valley--firm, and steadfast, and immovable in keeping the commandments of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-38', 'coc-bom-1908', 'I Nephi', 1, 38, 'Now this he spake because of the stiff-neckedness of Laman and Lemuel;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-39', 'coc-bom-1908', 'I Nephi', 1, 39, 'And this they said he had done because of the foolish imaginations of his heart.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-40', 'coc-bom-1908', 'I Nephi', 1, 40, 'And thus Laman and Lemuel, being the eldest, did murmur against their father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-41', 'coc-bom-1908', 'I Nephi', 1, 41, 'And they did murmur because they knew not the dealings of that God who had created them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-42', 'coc-bom-1908', 'I Nephi', 1, 42, 'Neither did they believe that Jerusalem, that great city, could be destroyed according to the words of the prophets.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-43', 'coc-bom-1908', 'I Nephi', 1, 43, 'And they were like unto the Jews, who were at Jerusalem, who sought to take away the life of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-44', 'coc-bom-1908', 'I Nephi', 1, 44, 'And it came to pass that my father did speak unto them in the valley of Lemuel, with power, being filled with the Spirit, until their frames did shake before him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-45', 'coc-bom-1908', 'I Nephi', 1, 45, 'And he did confound them, that they durst not utter against him;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-46', 'coc-bom-1908', 'I Nephi', 1, 46, 'And my father dwelt in a tent.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-47', 'coc-bom-1908', 'I Nephi', 1, 47, 'And it came to pass that I, Nephi, being exceeding young, nevertheless, being large in stature, and also having great desires to know of the mysteries of God,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-48', 'coc-bom-1908', 'I Nephi', 1, 48, 'Wherefore, I did cry unto the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-49', 'coc-bom-1908', 'I Nephi', 1, 49, 'And I spake unto Sam, making known unto him the things which the Lord had manifested unto me by his Holy Spirit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-50', 'coc-bom-1908', 'I Nephi', 1, 50, 'And it came to pass that he believed in my words;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-51', 'coc-bom-1908', 'I Nephi', 1, 51, 'But behold, Laman and Lemuel would not hearken unto my words;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-52', 'coc-bom-1908', 'I Nephi', 1, 52, 'And being grieved because of the hardness of their hearts, I cried unto the Lord for them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-53', 'coc-bom-1908', 'I Nephi', 1, 53, 'And it came to pass that the Lord spake unto me, saying, Blessed art thou, Nephi, because of thy faith;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-54', 'coc-bom-1908', 'I Nephi', 1, 54, 'And inasmuch as ye shall keep my commandments, ye shall prosper and shall be led to a land of promise, yea, even a land which I have prepared for you, yea, a land which is choice above all other lands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-55', 'coc-bom-1908', 'I Nephi', 1, 55, 'And inasmuch as thy brethren shall rebel against thee, they shall be cut off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-56', 'coc-bom-1908', 'I Nephi', 1, 56, 'And inasmuch as thou shalt keep my commandments, thou shalt be made a ruler and a teacher over thy brethren.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-57', 'coc-bom-1908', 'I Nephi', 1, 57, 'For behold, in that day that they shall rebel against me, I will curse them even with a sore curse;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-58', 'coc-bom-1908', 'I Nephi', 1, 58, 'And if it so be that they rebel against me, they shall be a scourge unto thy seed, to stir them up in the ways of remembrance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-59', 'coc-bom-1908', 'I Nephi', 1, 59, 'And it came to pass that I, Nephi, returned from speaking with the Lord, to the tent of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-60', 'coc-bom-1908', 'I Nephi', 1, 60, 'And it came to pass that he spake unto me, saying, Behold, I have dreamed a dream, in the which the Lord hath commanded me that thou and thy brethren shall return to Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-61', 'coc-bom-1908', 'I Nephi', 1, 61, 'For behold, Laban hath the record of the Jews and also a genealogy of thy forefathers, and they are engraven upon plates of brass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-62', 'coc-bom-1908', 'I Nephi', 1, 62, 'Wherefore, the Lord hath commanded me that thou and thy brothers should go unto the house of Laban, and seek the records, and bring them down hither into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-63', 'coc-bom-1908', 'I Nephi', 1, 63, 'And now, behold, thy brothers murmur, saying it is a hard thing which I have required of them;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-64', 'coc-bom-1908', 'I Nephi', 1, 64, 'Therefore, go, my son, and thou shalt be favored of the Lord because thou hast not murmured.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-65', 'coc-bom-1908', 'I Nephi', 1, 65, 'And it came to pass that I, Nephi, said unto my father, I will go and do the things which the Lord hath commanded;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-66', 'coc-bom-1908', 'I Nephi', 1, 66, 'And it came to pass that when my father had heard these words, he was exceeding glad, for he knew that I had been blessed of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-67', 'coc-bom-1908', 'I Nephi', 1, 67, 'And I, Nephi, and my brethren took our journey in the wilderness with our tents, to go up to the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-68', 'coc-bom-1908', 'I Nephi', 1, 68, 'And it came to pass that when we had come up to the land of Jerusalem, I and my brethren did consult one with another;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-69', 'coc-bom-1908', 'I Nephi', 1, 69, 'And it came to pass that the lot fell upon Laman;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-70', 'coc-bom-1908', 'I Nephi', 1, 70, 'And he desired of Laban the records which were engraven upon the plates of brass, which contained the genealogy of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-71', 'coc-bom-1908', 'I Nephi', 1, 71, 'And behold, it came to pass that Laban was angry and thrust him out from his presence;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-72', 'coc-bom-1908', 'I Nephi', 1, 72, 'Wherefore, he said unto him, Behold, thou art a robber, and I will slay thee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-73', 'coc-bom-1908', 'I Nephi', 1, 73, 'But Laman fled out of his presence and told the things which Laban had done, unto us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-74', 'coc-bom-1908', 'I Nephi', 1, 74, 'And we began to be exceeding sorrowful, and my brethren were about to return unto my father in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-75', 'coc-bom-1908', 'I Nephi', 1, 75, 'But behold, I said unto them, that as the Lord liveth, and as we live, we will not go down unto our father in the wilderness until we have accomplished the thing which the Lord hath commanded us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-76', 'coc-bom-1908', 'I Nephi', 1, 76, 'Wherefore, let us be faithful in keeping the commandments of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-77', 'coc-bom-1908', 'I Nephi', 1, 77, 'Therefore, let us go down to the land of our father''s inheritance;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-78', 'coc-bom-1908', 'I Nephi', 1, 78, 'And all this he hath done because of the commandments of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-79', 'coc-bom-1908', 'I Nephi', 1, 79, 'For behold, they have rejected the words of the prophets--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-80', 'coc-bom-1908', 'I Nephi', 1, 80, 'Wherefore, if my father should dwell in the land after he hath been commanded to flee out of the land, behold, he would also perish.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-81', 'coc-bom-1908', 'I Nephi', 1, 81, 'Wherefore, it must needs be that he flee out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-82', 'coc-bom-1908', 'I Nephi', 1, 82, 'And behold, it is wisdom in God that we should obtain these records, that we may preserve unto our children the language of our fathers,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-83', 'coc-bom-1908', 'I Nephi', 1, 83, 'And also that we may preserve unto them the words which have been spoken by the mouth of all the holy prophets, which have been delivered unto them by the Spirit and power of God since the world began, even down unto this present time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-84', 'coc-bom-1908', 'I Nephi', 1, 84, 'And it came to pass that after this manner of language did I persuade my brethren, that they might be faithful in keeping the commandments of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-85', 'coc-bom-1908', 'I Nephi', 1, 85, 'And it came to pass that we went down to the land of our inheritance, and we did gather together our gold, and our silver, and our precious things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-86', 'coc-bom-1908', 'I Nephi', 1, 86, 'And after we had gathered these things together, we went up again unto the house of Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-87', 'coc-bom-1908', 'I Nephi', 1, 87, 'And it came to pass that we went in unto Laban and desired him that he would give unto us the records which were engraven upon the plates of brass, for which we would give unto him our gold, and our silver, and all our precious things.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-88', 'coc-bom-1908', 'I Nephi', 1, 88, 'And it came to pass that when Laban saw our property, that it was exceeding great, he did lust after it, insomuch that he thrust us out and sent his servants to slay us, that he might obtain our property.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-89', 'coc-bom-1908', 'I Nephi', 1, 89, 'And it came to pass that we did flee before the servants of Laban;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-90', 'coc-bom-1908', 'I Nephi', 1, 90, 'And it came to pass that we fled into the wilderness, and the servants of Laban did not overtake us, and we hid ourselves in the cavity of a rock.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-91', 'coc-bom-1908', 'I Nephi', 1, 91, 'And it came to pass that Laman was angry with me and also with my father, and also was Lemuel;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-92', 'coc-bom-1908', 'I Nephi', 1, 92, 'Wherefore, Laman and Lemuel did speak many hard words unto us, their younger brothers, and they did smite us even with a rod.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-93', 'coc-bom-1908', 'I Nephi', 1, 93, 'And it came to pass as they smote us with a rod, behold, an angel of the Lord came and stood before them;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-94', 'coc-bom-1908', 'I Nephi', 1, 94, 'Know ye not that the Lord hath chosen him to be a ruler over you, and this because of your iniquities?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-95', 'coc-bom-1908', 'I Nephi', 1, 95, 'Behold, ye shall go up to Jerusalem again, and the Lord will deliver Laban into your hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-96', 'coc-bom-1908', 'I Nephi', 1, 96, 'And after the angel had spoken unto us, he departed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-97', 'coc-bom-1908', 'I Nephi', 1, 97, 'And after the angel had departed, Laman and Lemuel again began to murmur, saying, How is it possible that the Lord will deliver Laban into our hands?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-98', 'coc-bom-1908', 'I Nephi', 1, 98, 'Behold, he is a mighty man, and he can command fifty;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-99', 'coc-bom-1908', 'I Nephi', 1, 99, 'And it came to pass that I spake unto my brethren, saying, Let us go up again unto Jerusalem, and let us be faithful in keeping the commandments of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-100', 'coc-bom-1908', 'I Nephi', 1, 100, 'Therefore, let us go up;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-101', 'coc-bom-1908', 'I Nephi', 1, 101, 'Now behold, ye know that this is true;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-102', 'coc-bom-1908', 'I Nephi', 1, 102, 'Let us go up;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-103', 'coc-bom-1908', 'I Nephi', 1, 103, 'Now when I had spoken these words, they were yet wroth and did still continue to murmur;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-104', 'coc-bom-1908', 'I Nephi', 1, 104, 'And it was by night, and I caused that they should hide themselves without the walls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-105', 'coc-bom-1908', 'I Nephi', 1, 105, 'And after they had hid themselves, I, Nephi, crept into the city and went forth towards the house of Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-106', 'coc-bom-1908', 'I Nephi', 1, 106, 'And I was led by the Spirit, not knowing beforehand the things which I should do.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-107', 'coc-bom-1908', 'I Nephi', 1, 107, 'Nevertheless, I went forth;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-108', 'coc-bom-1908', 'I Nephi', 1, 108, 'And when I came to him, I found that it was Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-109', 'coc-bom-1908', 'I Nephi', 1, 109, 'And I beheld his sword, and I drew it forth from the sheath thereof;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-110', 'coc-bom-1908', 'I Nephi', 1, 110, 'And it came to pass that I was constrained by the Spirit that I should kill Laban;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-111', 'coc-bom-1908', 'I Nephi', 1, 111, 'But I said in my heart, Never at any time have I shed the blood of man;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-112', 'coc-bom-1908', 'I Nephi', 1, 112, 'And the Spirit said unto me again, Behold, the Lord hath delivered him into thy hands;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-113', 'coc-bom-1908', 'I Nephi', 1, 113, 'And it came to pass that the Spirit said unto me again, Slay him, for the Lord hath delivered him into thy hands.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-114', 'coc-bom-1908', 'I Nephi', 1, 114, 'Behold, the Lord slayeth the wicked to bring forth his righteous purposes.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-115', 'coc-bom-1908', 'I Nephi', 1, 115, 'It is better that one man should perish than that a nation should dwindle and perish in unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-116', 'coc-bom-1908', 'I Nephi', 1, 116, 'And now, when I, Nephi, had heard these words, I remembered the words of the Lord which he spake unto me in the wilderness, saying that, Inasmuch as thy seed shall keep my commandments, they shall prosper in the land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-117', 'coc-bom-1908', 'I Nephi', 1, 117, 'Yea, and I also thought that they could not keep the commandments of the Lord according to the law of Moses, save they should have the law.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-118', 'coc-bom-1908', 'I Nephi', 1, 118, 'And I also knew that the law was engraven upon the plates of brass.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-119', 'coc-bom-1908', 'I Nephi', 1, 119, 'And again, I knew that the Lord had delivered Laban into my hands for this cause, that I might obtain the records according to his commandments.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-120', 'coc-bom-1908', 'I Nephi', 1, 120, 'Therefore, I did obey the voice of the Spirit and took Laban by the hair of the head;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-121', 'coc-bom-1908', 'I Nephi', 1, 121, 'And after I had smitten off his head with his own sword, I took the garments of Laban and put them upon mine own body, yea, even every whit;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-122', 'coc-bom-1908', 'I Nephi', 1, 122, 'And after I had done this, I went forth unto the treasury of Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-123', 'coc-bom-1908', 'I Nephi', 1, 123, 'And as I went forth towards the treasury of Laban, behold, I saw the servant of Laban, who had the keys of the treasury.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-124', 'coc-bom-1908', 'I Nephi', 1, 124, 'And I commanded him in the voice of Laban that he should go with me into the treasury;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-125', 'coc-bom-1908', 'I Nephi', 1, 125, 'And he spake unto me concerning the elders of the Jews, he knowing that his master Laban had been out by night among them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-126', 'coc-bom-1908', 'I Nephi', 1, 126, 'And I spake unto him as if it had been Laban.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-127', 'coc-bom-1908', 'I Nephi', 1, 127, 'And I also spake unto him that I should carry the engravings which were upon the plates of brass to my elder brethren, who were without the walls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-128', 'coc-bom-1908', 'I Nephi', 1, 128, 'And I also bade him that he should follow me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-129', 'coc-bom-1908', 'I Nephi', 1, 129, 'And he, supposing that I spake of the brethren of the church and that I was truly that Laban whom I had slain, wherefore, he did follow me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-130', 'coc-bom-1908', 'I Nephi', 1, 130, 'And he spake unto me many times concerning the elders of the Jews as I went forth unto my brethren, who were without the walls.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-131', 'coc-bom-1908', 'I Nephi', 1, 131, 'And it came to pass that when Laman saw me, he was exceedingly frightened, and also Lemuel and Sam.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-132', 'coc-bom-1908', 'I Nephi', 1, 132, 'And they fled from before my presence;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-133', 'coc-bom-1908', 'I Nephi', 1, 133, 'And it came to pass that I called after them, and they did hear me;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-134', 'coc-bom-1908', 'I Nephi', 1, 134, 'And it came to pass that when the servant of Laban beheld my brethren, he began to tremble and was about to flee from before me and return to the city of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-135', 'coc-bom-1908', 'I Nephi', 1, 135, 'And now, I, Nephi, being a man large in stature, and also having received much strength of the Lord, therefore, I did seize upon the servant of Laban and held him that he should not flee.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-136', 'coc-bom-1908', 'I Nephi', 1, 136, 'And it came to pass that I spake with him, that if he would hearken unto my words, as the Lord liveth and as I live, even so, that if he would hearken unto our words, we would spare his life.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-137', 'coc-bom-1908', 'I Nephi', 1, 137, 'And I spake unto him, even with an oath, that he need not fear--that he should be a free man like unto us if he would go down in the wilderness with us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-138', 'coc-bom-1908', 'I Nephi', 1, 138, 'And I also spake unto him, saying, Surely the Lord hath commanded us to do this thing. And shall we not be diligent in keeping the commandments of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-139', 'coc-bom-1908', 'I Nephi', 1, 139, 'Therefore, if thou wilt go down into the wilderness to my father, thou shalt have place with us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-140', 'coc-bom-1908', 'I Nephi', 1, 140, 'And it came to pass that Zoram did take courage at the words which I spake.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-141', 'coc-bom-1908', 'I Nephi', 1, 141, 'Now Zoram was the name of the servant;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-142', 'coc-bom-1908', 'I Nephi', 1, 142, 'And he also made an oath unto us that he would tarry with us from that time forth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-143', 'coc-bom-1908', 'I Nephi', 1, 143, 'Now we were desirous that he should tarry with us for this cause, that the Jews might not know concerning our flight into the wilderness, lest they should pursue us and destroy us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-144', 'coc-bom-1908', 'I Nephi', 1, 144, 'And it came to pass that when Zoram had made an oath unto us, our fears did cease concerning him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-145', 'coc-bom-1908', 'I Nephi', 1, 145, 'And it came to pass that we took the plates of brass and the servant of Laban, and departed into the wilderness, and journeyed unto the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-146', 'coc-bom-1908', 'I Nephi', 1, 146, 'And it came to pass that after we had come down into the wilderness unto our father, behold, he was filled with joy;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-147', 'coc-bom-1908', 'I Nephi', 1, 147, 'And she also had complained against my father, telling him that he was a visionary man, saying, Behold, thou hast led us forth from the land of our inheritance, and my sons are no more, and we perish in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-148', 'coc-bom-1908', 'I Nephi', 1, 148, 'And after this manner of language had my mother complained against my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-149', 'coc-bom-1908', 'I Nephi', 1, 149, 'And it had come to pass that my father spake unto her, saying, I know that I am a visionary man;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-150', 'coc-bom-1908', 'I Nephi', 1, 150, 'But behold, I have obtained a land of promise, in the which things I do rejoice;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-151', 'coc-bom-1908', 'I Nephi', 1, 151, 'Yea, and I know that the Lord will deliver my sons out of the hands of Laban and bring them down again unto us in the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-152', 'coc-bom-1908', 'I Nephi', 1, 152, 'And after this manner of language did my father Lehi comfort my mother Sariah concerning us, while we journeyed in the wilderness up to the land of Jerusalem to obtain the record of the Jews.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-153', 'coc-bom-1908', 'I Nephi', 1, 153, 'And when we had returned to the tent of my father, behold, their joy was full, and my mother was comforted;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-154', 'coc-bom-1908', 'I Nephi', 1, 154, 'And she spake, saying, Now I know of a surety that the Lord hath commanded my husband to flee into the wilderness;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-155', 'coc-bom-1908', 'I Nephi', 1, 155, 'Yea, and I also know of a surety that the Lord hath protected my sons, and delivered them out of the hands of Laban, and gave them power whereby they could accomplish the thing which the Lord hath commanded them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-156', 'coc-bom-1908', 'I Nephi', 1, 156, 'And after this manner of language did she speak.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-157', 'coc-bom-1908', 'I Nephi', 1, 157, 'And it came to pass that they did rejoice exceedingly and did offer sacrifice and burnt offerings unto the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-158', 'coc-bom-1908', 'I Nephi', 1, 158, 'And after they had given thanks unto the God of Israel, my father Lehi took the records which were engraven upon the plates of brass, and he did search them from the beginning.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-159', 'coc-bom-1908', 'I Nephi', 1, 159, 'And he beheld that they did contain the five books of Moses, which gave an account of the creation of the world,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-160', 'coc-bom-1908', 'I Nephi', 1, 160, 'And also of Adam and Eve, who were our first parents,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-161', 'coc-bom-1908', 'I Nephi', 1, 161, 'And also a record of the Jews from the beginning, even down to the commencement of the reign of Zedekiah, king of Judah,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-162', 'coc-bom-1908', 'I Nephi', 1, 162, 'And also the prophecies of the holy prophets, from the beginning, even down to the commencement of the reign of Zedekiah,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-163', 'coc-bom-1908', 'I Nephi', 1, 163, 'And also many prophecies which have been spoken by the mouth of Jeremiah.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-164', 'coc-bom-1908', 'I Nephi', 1, 164, 'And it came to pass that my father Lehi also found upon the plates of brass a genealogy of his fathers;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-165', 'coc-bom-1908', 'I Nephi', 1, 165, 'Wherefore, he knew that he was a descendant of Joseph, yea, even that Joseph who was the son of Jacob, who was sold into Egypt and who was preserved by the hand of the Lord, that he might preserve his father Jacob and all his household from perishing with famine.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-166', 'coc-bom-1908', 'I Nephi', 1, 166, 'And they were also led out of captivity and out of the land of Egypt by that same God who had preserved them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-167', 'coc-bom-1908', 'I Nephi', 1, 167, 'And thus my father Lehi did discover the genealogy of his fathers.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-168', 'coc-bom-1908', 'I Nephi', 1, 168, 'And Laban also was a descendant of Joseph;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-169', 'coc-bom-1908', 'I Nephi', 1, 169, 'And now, when my father saw all these things, he was filled with the Spirit and began to prophesy concerning his seed--that these plates of brass should go forth unto all nations, kindreds, tongues, and people who were of his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-170', 'coc-bom-1908', 'I Nephi', 1, 170, 'Wherefore, he said that these plates of brass should never perish, neither should they be dimmed any more by time.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-171', 'coc-bom-1908', 'I Nephi', 1, 171, 'And he prophesied many things concerning his seed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-172', 'coc-bom-1908', 'I Nephi', 1, 172, 'And it came to pass that, thus far, I and my father had kept the commandments wherewith the Lord had commanded us.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-173', 'coc-bom-1908', 'I Nephi', 1, 173, 'And we had obtained the records which the Lord had commanded us, and searched them, and found that they were desirable, yea, even of great worth unto us, insomuch that we could preserve the commandments of the Lord unto our children.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-1-174', 'coc-bom-1908', 'I Nephi', 1, 174, 'Wherefore, it was wisdom in the Lord that we should carry them with us as we journeyed in the wilderness towards the land of promise.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-1', 'coc-bom-1908', 'I Nephi', 2, 1, 'And now, I, Nephi, do not give the genealogy of my fathers in this part of my record;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-2', 'coc-bom-1908', 'I Nephi', 2, 2, 'For it sufficeth me to say that we are a descendant of Joseph.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-3', 'coc-bom-1908', 'I Nephi', 2, 3, 'And it mattereth not to me that I am particular to give a full account of all the things of my father, for they cannot be written upon these plates, for I desire the room that I may write of the things of God.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-4', 'coc-bom-1908', 'I Nephi', 2, 4, 'For the fullness of mine intent is that I may persuade men to come unto the God of Abraham, and the God of Isaac, and the God of Jacob, and be saved.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-5', 'coc-bom-1908', 'I Nephi', 2, 5, 'Wherefore, the things which are pleasing unto the world, I do not write, but the things which are pleasing unto God and unto those who are not of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-6', 'coc-bom-1908', 'I Nephi', 2, 6, 'Wherefore, I shall give commandment unto my seed that they shall not occupy these plates with things which are not of worth unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-7', 'coc-bom-1908', 'I Nephi', 2, 7, 'And now, I would that ye might know that after my father Lehi had made an end of prophesying concerning his seed, it came to pass that the Lord spake unto him again, saying that it was not meet for him, Lehi, that he should take his family into the wilderness alone;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-8', 'coc-bom-1908', 'I Nephi', 2, 8, 'And it came to pass that the Lord commanded him that I, Nephi, and my brethren should again return unto the land of Jerusalem and bring down Ishmael and his family into the wilderness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-9', 'coc-bom-1908', 'I Nephi', 2, 9, 'And it came to pass that I, Nephi, did again, with my brethren, go forth into the wilderness to go up to Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-10', 'coc-bom-1908', 'I Nephi', 2, 10, 'And it came to pass that we went up unto the house of Ishmael, and we did gain favor in the sight of Ishmael, insomuch that we did speak unto him the words of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-11', 'coc-bom-1908', 'I Nephi', 2, 11, 'And it came to pass that the Lord did soften the heart of Ishmael and also his household, insomuch that they took their journey with us down into the wilderness to the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-12', 'coc-bom-1908', 'I Nephi', 2, 12, 'And it came to pass that as we journeyed in the wilderness, behold, Laman and Lemuel, and two of the daughters of Ishmael, and the two sons of Ishmael, and their families did rebel against us--yea, against me, Nephi, and Sam, and their father Ishmael, and his wife, and his three other daughters.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-13', 'coc-bom-1908', 'I Nephi', 2, 13, 'And it came to pass in the which rebellion they were desirous to return unto the land of Jerusalem.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-14', 'coc-bom-1908', 'I Nephi', 2, 14, 'And now, I, Nephi, being grieved for the hardness of their hearts, therefore, I spake unto them, saying, yea, even unto Laman and unto Lemuel, Behold, ye are mine elder brethren. And how is it that ye are so hard in your hearts, and so blind in your minds, that ye have need that I, your younger brother, should speak unto you, yea, and set an example for you?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-15', 'coc-bom-1908', 'I Nephi', 2, 15, 'How is it that ye have not hearkened unto the word of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-16', 'coc-bom-1908', 'I Nephi', 2, 16, 'How is it that ye have forgotten that ye have seen an angel of the Lord?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-17', 'coc-bom-1908', 'I Nephi', 2, 17, 'Yea, and how is it that ye have forgotten what great things the Lord hath done for us in delivering us out of the hands of Laban, and also that we should obtain the record?', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-18', 'coc-bom-1908', 'I Nephi', 2, 18, 'Yea, and how is it that ye have forgotten that the Lord is able to do all things according to his will for the children of men if it so be that they exercise faith in him? Wherefore, let us be faithful to him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-19', 'coc-bom-1908', 'I Nephi', 2, 19, 'And if it so be that we are faithful to him, we shall obtain the land of promise;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-20', 'coc-bom-1908', 'I Nephi', 2, 20, 'For all things which the Lord hath spoken concerning the destruction of Jerusalem must be fulfilled.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-21', 'coc-bom-1908', 'I Nephi', 2, 21, 'For behold, the Spirit of the Lord ceaseth soon to strive with them;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-22', 'coc-bom-1908', 'I Nephi', 2, 22, 'For behold, they have rejected the prophets, and Jeremiah have they cast into prison.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-23', 'coc-bom-1908', 'I Nephi', 2, 23, 'And they have sought to take away the life of my father, insomuch that they have driven him out of the land.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-24', 'coc-bom-1908', 'I Nephi', 2, 24, 'Now behold, I say unto you that if ye will return unto Jerusalem, ye shall also perish with them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-25', 'coc-bom-1908', 'I Nephi', 2, 25, 'And now, if ye have choice, go up to the land and remember the words which I speak unto you, that if ye go, ye will also perish;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-26', 'coc-bom-1908', 'I Nephi', 2, 26, 'And it came to pass that when I, Nephi, had spoken these words unto my brethren, they were angry with me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-27', 'coc-bom-1908', 'I Nephi', 2, 27, 'And it came to pass that they did lay their hands upon me--for behold, they were exceeding wroth--and they did bind me with cords, for they sought to take away my life, that they might leave me in the wilderness to be devoured by wild beasts.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-28', 'coc-bom-1908', 'I Nephi', 2, 28, 'But it came to pass that I prayed unto the Lord, saying, O Lord, according to my faith which is in thee, wilt thou deliver me from the hands of my brethren,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-29', 'coc-bom-1908', 'I Nephi', 2, 29, 'Yea, even give me strength that I may burst these bands with which I am bound.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-30', 'coc-bom-1908', 'I Nephi', 2, 30, 'And it came to pass that when I had said these words, behold, the bands were loosed from off my hands and feet, and I stood before my brethren, and I spake unto them again.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-31', 'coc-bom-1908', 'I Nephi', 2, 31, 'And it came to pass that they were angry with me again and sought to lay hands upon me;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-32', 'coc-bom-1908', 'I Nephi', 2, 32, 'But behold, one of the daughters of Ishmael, yea, and also her mother, and one of the sons of Ishmael did plead with my brethren, insomuch that they did soften their hearts;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-33', 'coc-bom-1908', 'I Nephi', 2, 33, 'And it came to pass that they were sorrowful because of their wickedness, insomuch that they did bow down before me and did plead with me that I would forgive them of the thing that they had done against me.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-34', 'coc-bom-1908', 'I Nephi', 2, 34, 'And it came to pass that I did frankly forgive them all that they had done, and I did exhort them that they would pray unto the Lord, their God, for forgiveness.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-35', 'coc-bom-1908', 'I Nephi', 2, 35, 'And it came to pass that they did so.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-36', 'coc-bom-1908', 'I Nephi', 2, 36, 'And after they had done praying unto the Lord, we did again travel on our journey toward the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-37', 'coc-bom-1908', 'I Nephi', 2, 37, 'And it came to pass that we did come down unto the tent of our father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-38', 'coc-bom-1908', 'I Nephi', 2, 38, 'And after I, and my brethren, and all the house of Ishmael had come down unto the tent of my father, they did give thanks unto the Lord, their God;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-39', 'coc-bom-1908', 'I Nephi', 2, 39, 'And they did offer sacrifice and burnt offerings unto him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-40', 'coc-bom-1908', 'I Nephi', 2, 40, 'And it came to pass that we had gathered together all manner of seeds of every kind--both of grain of every kind and also of the seeds of fruits of every kind.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-41', 'coc-bom-1908', 'I Nephi', 2, 41, 'And it came to pass that while my father tarried in the wilderness, he spake unto us, saying, Behold, I have dreamed a dream;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-42', 'coc-bom-1908', 'I Nephi', 2, 42, 'And behold, because of the thing which I have seen, I have reason to rejoice in the Lord because of Nephi and also of Sam;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-43', 'coc-bom-1908', 'I Nephi', 2, 43, 'But behold, Laman and Lemuel, I fear exceedingly because of you;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-44', 'coc-bom-1908', 'I Nephi', 2, 44, 'And it came to pass that I saw a man, and he was dressed in a white robe;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-45', 'coc-bom-1908', 'I Nephi', 2, 45, 'And it came to pass that he spake unto me and bade me follow him.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-46', 'coc-bom-1908', 'I Nephi', 2, 46, 'And it came to pass that as I followed him, I beheld myself that I was in a dark and dreary waste.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-47', 'coc-bom-1908', 'I Nephi', 2, 47, 'And after I had traveled for the space of many hours in darkness, I began to pray unto the Lord that he would have mercy on me according to the multitude of his tender mercies.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-48', 'coc-bom-1908', 'I Nephi', 2, 48, 'And it came to pass after I had prayed unto the Lord, I beheld a large and spacious field.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-49', 'coc-bom-1908', 'I Nephi', 2, 49, 'And it came to pass that I beheld a tree, whose fruit was desirable to make one happy.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-50', 'coc-bom-1908', 'I Nephi', 2, 50, 'And it came to pass that I did go forth and partake of the fruit thereof;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-51', 'coc-bom-1908', 'I Nephi', 2, 51, 'Yea, and I beheld that the fruit thereof was white, to exceed all the whiteness that I had ever seen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-52', 'coc-bom-1908', 'I Nephi', 2, 52, 'And as I partook of the fruit thereof, it filled my soul with exceeding great joy;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-53', 'coc-bom-1908', 'I Nephi', 2, 53, 'Wherefore, I began to be desirous that my family should partake of it also;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-54', 'coc-bom-1908', 'I Nephi', 2, 54, 'And as I cast my eyes round about, that perhaps I might discover my family also, I beheld a river of water;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-55', 'coc-bom-1908', 'I Nephi', 2, 55, 'And I looked to behold from whence it came;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-56', 'coc-bom-1908', 'I Nephi', 2, 56, 'And at the head thereof I beheld your mother Sariah, and Sam, and Nephi;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-57', 'coc-bom-1908', 'I Nephi', 2, 57, 'And it came to pass that I beckoned unto them;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-58', 'coc-bom-1908', 'I Nephi', 2, 58, 'And it came to pass that they did come unto me and partake of the fruit also.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-59', 'coc-bom-1908', 'I Nephi', 2, 59, 'And it came to pass that I was desirous that Laman and Lemuel should come and partake of the fruit also;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-60', 'coc-bom-1908', 'I Nephi', 2, 60, 'Wherefore, I cast mine eyes towards the head of the river, that perhaps I might see them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-61', 'coc-bom-1908', 'I Nephi', 2, 61, 'And it came to pass that I saw them, but they would not come unto me and partake of the fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-62', 'coc-bom-1908', 'I Nephi', 2, 62, 'And I beheld a rod of iron;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-63', 'coc-bom-1908', 'I Nephi', 2, 63, 'And I also beheld a straight and narrow path which came along by the rod of iron, even to the tree by which I stood;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-64', 'coc-bom-1908', 'I Nephi', 2, 64, 'And it also led by the head of the fountain unto a large and spacious field, as if it had been a world;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-65', 'coc-bom-1908', 'I Nephi', 2, 65, 'And I saw numberless concourses of people, many of whom were pressing forward, that they might obtain the path which led unto the tree by which I stood.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-66', 'coc-bom-1908', 'I Nephi', 2, 66, 'And it came to pass that they did come forth and commence in the path which led to the tree.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-67', 'coc-bom-1908', 'I Nephi', 2, 67, 'And it came to pass that there arose a mist of darkness, yea, even an exceeding great mist of darkness, insomuch that they who had commenced in the path did lose their way, that they wandered off and were lost.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-68', 'coc-bom-1908', 'I Nephi', 2, 68, 'And it came to pass that I beheld others pressing forward, and they came forth and caught hold of the end of the rod of iron;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-69', 'coc-bom-1908', 'I Nephi', 2, 69, 'And they did press forward through the mist of darkness, clinging to the rod of iron, even until they did come forth and partake of the fruit of the tree.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-70', 'coc-bom-1908', 'I Nephi', 2, 70, 'And after they had partaken of the fruit of the tree, they did cast their eyes about as if they were ashamed.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-71', 'coc-bom-1908', 'I Nephi', 2, 71, 'And I also cast my eyes round about and beheld on the other side of the river of water a great and spacious building;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-72', 'coc-bom-1908', 'I Nephi', 2, 72, 'And it stood as it were in the air, high above the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-73', 'coc-bom-1908', 'I Nephi', 2, 73, 'And it was filled with people, both old and young, both male and female;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-74', 'coc-bom-1908', 'I Nephi', 2, 74, 'And their manner of dress was exceeding fine;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-75', 'coc-bom-1908', 'I Nephi', 2, 75, 'And they were in the attitude of mocking and pointing their fingers towards those who had come at and were partaking of the fruit.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-76', 'coc-bom-1908', 'I Nephi', 2, 76, 'And after they had tasted of the fruit, they were ashamed because of those that were scoffing at them;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-77', 'coc-bom-1908', 'I Nephi', 2, 77, 'And now, I, Nephi, do not speak all the words of my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-78', 'coc-bom-1908', 'I Nephi', 2, 78, 'But, to be short in writing, behold, he saw other multitudes pressing forward;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-79', 'coc-bom-1908', 'I Nephi', 2, 79, 'And he also saw other multitudes feeling their way towards that great and spacious building.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-80', 'coc-bom-1908', 'I Nephi', 2, 80, 'And it came to pass that many were drowned in the depths of the fountain;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-81', 'coc-bom-1908', 'I Nephi', 2, 81, 'And many were lost from his view, wandering in strange roads.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-82', 'coc-bom-1908', 'I Nephi', 2, 82, 'And great was the multitude that did enter into that strange building.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-83', 'coc-bom-1908', 'I Nephi', 2, 83, 'And after they did enter into that building, they did point the finger of scorn at me and those that were partaking of the fruit also;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-84', 'coc-bom-1908', 'I Nephi', 2, 84, 'These are the words of my father: For as many as heeded them, had fallen away.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-85', 'coc-bom-1908', 'I Nephi', 2, 85, 'And Laman and Lemuel partook not of the fruit, said my father.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-86', 'coc-bom-1908', 'I Nephi', 2, 86, 'And it came to pass after my father had spoken all the words of his dream or vision, which were many, he said unto us, because of these things which he saw in a vision, he exceedingly feared for Laman and Lemuel;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-87', 'coc-bom-1908', 'I Nephi', 2, 87, 'Yea, he feared lest they should be cast off from the presence of the Lord.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-88', 'coc-bom-1908', 'I Nephi', 2, 88, 'And he did exhort them then, with all the feeling of a tender parent, that they would hearken to his words, that perhaps the Lord would be merciful to them and not cast them off;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-89', 'coc-bom-1908', 'I Nephi', 2, 89, 'Yea, my father did preach unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-90', 'coc-bom-1908', 'I Nephi', 2, 90, 'And after he had preached unto them and also prophesied unto them of many things, he bade them to keep the commandments of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-91', 'coc-bom-1908', 'I Nephi', 2, 91, 'And he did cease speaking unto them.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-92', 'coc-bom-1908', 'I Nephi', 2, 92, 'And all these things did my father see, and hear, and speak as he dwelt in a tent, in the valley of Lemuel--and also a great many more things, which cannot be written upon these plates.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-93', 'coc-bom-1908', 'I Nephi', 2, 93, 'And now, as I have spoken concerning these plates, behold, they are not the plates upon which I make a full account of the history of my people;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-94', 'coc-bom-1908', 'I Nephi', 2, 94, 'For the plates upon which I make a full account of my people, I have given the name of Nephi;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-95', 'coc-bom-1908', 'I Nephi', 2, 95, 'Wherefore, they are called the plates of Nephi after mine own name;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-96', 'coc-bom-1908', 'I Nephi', 2, 96, 'Nevertheless, I have received a commandment of the Lord that I should make these plates for the special purpose, that there should be an account engraven of the ministry of my people.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-97', 'coc-bom-1908', 'I Nephi', 2, 97, 'Upon the other plates should be engraven an account of the reign of the kings and the wars and contentions of my people;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-98', 'coc-bom-1908', 'I Nephi', 2, 98, 'Wherefore, these plates are for the more part of the ministry;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-99', 'coc-bom-1908', 'I Nephi', 2, 99, 'Wherefore, the Lord hath commanded me to make these plates for a wise purpose in him, which purpose I know not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-100', 'coc-bom-1908', 'I Nephi', 2, 100, 'But the Lord knoweth all things from the beginning;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-101', 'coc-bom-1908', 'I Nephi', 2, 101, 'Wherefore, he prepareth a way to accomplish all his works among the children of men;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-2-102', 'coc-bom-1908', 'I Nephi', 2, 102, 'And thus it is. Amen.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-1', 'coc-bom-1908', 'I Nephi', 3, 1, 'And now, I, Nephi, proceed to give an account upon these plates of my proceedings, and my reign, and ministry;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-2', 'coc-bom-1908', 'I Nephi', 3, 2, 'For behold, it came to pass, after my father had made an end of speaking the words of his dream and also of exhorting them to all diligence, he spake unto them concerning the Jews, that after they should be destroyed--even that great city Jerusalem, and many be carried away captive into Babylon--according to the own due time of the Lord they should return again, yea, even be brought back out of captivity;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-3', 'coc-bom-1908', 'I Nephi', 3, 3, 'And after they should be brought back out of captivity, they should possess again the land of their inheritance.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-4', 'coc-bom-1908', 'I Nephi', 3, 4, 'Yea, even six hundred years from the time that my father left Jerusalem, a prophet would the Lord God raise up among the Jews, even a Messiah or, in other words, a Savior of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-5', 'coc-bom-1908', 'I Nephi', 3, 5, 'And he also spake concerning the prophets--how great a number had testified of these things concerning this Messiah of whom he had spoken, or this Redeemer of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-6', 'coc-bom-1908', 'I Nephi', 3, 6, 'Wherefore, all mankind were in a lost and in a fallen state and ever would be, save they should rely on this Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-7', 'coc-bom-1908', 'I Nephi', 3, 7, 'And he spake also concerning a prophet, who should come before the Messiah to prepare the way of the Lord;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-8', 'coc-bom-1908', 'I Nephi', 3, 8, 'Yea, even he should go forth and cry in the wilderness, Prepare ye the way of the Lord and make his paths straight;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-9', 'coc-bom-1908', 'I Nephi', 3, 9, 'For there standeth one among you whom ye know not;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-10', 'coc-bom-1908', 'I Nephi', 3, 10, 'And much spake my father concerning this thing.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-11', 'coc-bom-1908', 'I Nephi', 3, 11, 'And my father said he should baptize in Bethabara, beyond Jordan;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-12', 'coc-bom-1908', 'I Nephi', 3, 12, 'And after he had baptized the Messiah with water, he should behold and bear record that he had baptized the Lamb of God, who should take away the sins of the world.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-13', 'coc-bom-1908', 'I Nephi', 3, 13, 'And it came to pass after my father had spoken these words, he spake unto my brethren concerning the gospel which should be preached among the Jews,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-14', 'coc-bom-1908', 'I Nephi', 3, 14, 'And also concerning the dwindling of the Jews in unbelief.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-15', 'coc-bom-1908', 'I Nephi', 3, 15, 'And after they had slain the Messiah who should come, and after he had been slain, he should rise from the dead and should make himself manifest by the Holy Ghost unto the Gentiles.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-16', 'coc-bom-1908', 'I Nephi', 3, 16, 'Yea, even my father spake much concerning the Gentiles and also concerning the house of Israel, that they should be compared like unto an olive tree, whose branches should be broken off and should be scattered upon all the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-17', 'coc-bom-1908', 'I Nephi', 3, 17, 'Wherefore, he said it must needs be that we should be led with one accord into the land of promise, unto the fulfilling of the word of the Lord that we should be scattered upon all the face of the earth.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-18', 'coc-bom-1908', 'I Nephi', 3, 18, 'And after the house of Israel should be scattered, they should be gathered together again;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-19', 'coc-bom-1908', 'I Nephi', 3, 19, 'Or, in fine, after the Gentiles had received the fullness of the gospel, the natural branches of the olive tree, or the remnants of the house of Israel, should be grafted in, or come to the knowledge of the true Messiah, their Lord and their Redeemer.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-20', 'coc-bom-1908', 'I Nephi', 3, 20, 'And after this manner of language did my father prophesy and speak unto my brethren,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-21', 'coc-bom-1908', 'I Nephi', 3, 21, 'And also many more things, which I do not write in this book;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-22', 'coc-bom-1908', 'I Nephi', 3, 22, 'And all these things of which I have spoken were done as my father dwelt in a tent in the valley of Lemuel.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-23', 'coc-bom-1908', 'I Nephi', 3, 23, 'And it came to pass after I, Nephi, having heard all the words of my father concerning the things which he saw in a vision,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-24', 'coc-bom-1908', 'I Nephi', 3, 24, 'And also the things which he spake by the power of the Holy Ghost, which power he received by faith on the Son of God--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-25', 'coc-bom-1908', 'I Nephi', 3, 25, 'And the Son of God was the Messiah who should come--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-26', 'coc-bom-1908', 'I Nephi', 3, 26, 'I, Nephi, was desirous also that I might see, and hear, and know of these things by the power of the Holy Ghost, which is the gift of God unto all those who diligently seek him, as well in times of old as in the time that he should manifest himself unto the children of men.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-27', 'coc-bom-1908', 'I Nephi', 3, 27, 'For he is the same yesterday, today, and forever.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-28', 'coc-bom-1908', 'I Nephi', 3, 28, 'And the way is prepared from the foundation of the world if it so be that they repent and come unto him;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-29', 'coc-bom-1908', 'I Nephi', 3, 29, 'For he that diligently seeketh shall find;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-30', 'coc-bom-1908', 'I Nephi', 3, 30, 'And the mysteries of God shall be unfolded unto them by the power of the Holy Ghost, as well in this time as in times of old,', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-31', 'coc-bom-1908', 'I Nephi', 3, 31, 'And as well in times of old as in times to come;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-32', 'coc-bom-1908', 'I Nephi', 3, 32, 'Wherefore, the course of the Lord is one eternal round.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-33', 'coc-bom-1908', 'I Nephi', 3, 33, 'Therefore, remember, O man, for all thy doings thou shalt be brought into judgment.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-34', 'coc-bom-1908', 'I Nephi', 3, 34, 'Wherefore, if ye have sought to do wickedly in the days of your probation, then ye are found unclean before the judgment seat of God;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-35', 'coc-bom-1908', 'I Nephi', 3, 35, 'And no unclean thing can dwell with God;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-36', 'coc-bom-1908', 'I Nephi', 3, 36, 'And the Holy Ghost giveth authority that I should speak these things and deny them not.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-37', 'coc-bom-1908', 'I Nephi', 3, 37, 'For it came to pass after I had desired to know the things that my father had seen--and believing that the Lord was able to make them known unto me--', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-38', 'coc-bom-1908', 'I Nephi', 3, 38, 'As I sat pondering in mine heart, I was caught away in the Spirit of the Lord, yea, into an exceeding high mountain, which I never had before seen and upon which I never had before set my foot.', 'standard')
ON CONFLICT (id) DO NOTHING;
INSERT INTO verses (id, edition_id, book, chapter, verse, text, verse_type)
VALUES ('coc-bom-1908:i-nephi-3-39', 'coc-bom-1908', 'I Nephi', 3, 39, 'And the Spirit said unto me, Behold, what desirest thou?', 'standard')
ON CONFLICT (id) DO NOTHING;
